// All patient-facing wording lives here, so the screen and the PDF always say the same thing.

export const SHORT_DISCLAIMER =
  "Preliminary clinical screening suggestion. Consult a healthcare professional for validation.";

export const LONG_DISCLAIMER =
  "This report is generated by machine-learning screening models trained on public datasets. It is an educational " +
  "screening aid and is not a medical diagnosis. It cannot replace an examination by a qualified clinician. " +
  "Do not start, stop or change any treatment based on this report. If you feel unwell or have severe symptoms such as " +
  "chest pain, seek medical care immediately.";

// Flask returns prediction 1 = elevated risk, 0 = lower risk
export const riskText = (prediction) =>
  prediction === 1
    ? { label: "Elevated Risk Indicated", short: "Elevated risk", high: true }
    : { label: "Lower Risk Indicated", short: "Lower risk", high: false };

export const nextStep = (prediction, specialty) =>
  prediction === 1
    ? `This screening indicates an elevated risk. A consultation with a ${specialty} is advisable for clinical evaluation and confirmatory testing.`
    : `This screening indicates a lower risk. Continue regular health check-ups and seek medical advice if symptoms develop. A ${specialty} can be consulted at any time.`;

// Random Forest "confidence" -> plain-English strength of match
export const matchStrength = (confidence) =>
  confidence >= 70 ? "Strong symptom match" : confidence >= 40 ? "Moderate symptom match" : "Limited certainty";

export const LOW_CONFIDENCE_MESSAGE =
  "The reported symptoms overlap with several conditions, so this suggestion carries limited certainty.";

export const CONFIDENCE_FOOTNOTE =
  "Confidence reflects the level of agreement among the screening model's 100 internal assessments. It is a screening indicator, not a clinical probability.";

export const SERVICE_UNAVAILABLE =
  "The analysis service is temporarily unavailable. Please try again in a few moments.";
